int main(){
    int n; scanf("%d",&n);
    vector<long long> x(n+1),y(n+1),c(n+1),k(n+1);
    for(int i=1;i<=n;i++) scanf("%lld %lld",&x[i],&y[i]);
    for(int i=1;i<=n;i++) scanf("%lld",&c[i]);
    for(int i=1;i<=n;i++) scanf("%lld",&k[i]);
    vector<long long> d(n+1,LLONG_MAX); vector<int> par(n+1,0); vector<bool> in(n+1,false);
