using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        long long n; scanf("%lld",&n);
        long long T=n-1;                       // sum of c_1..c_d must equal n-1
        int d=1;
        while((1LL<<(d+1))-2 < T) d++;         // smallest d with max sum 2^{d+1}-2 >= T
        vector<long long> s(d);
        long long p=1, R=T;                    // p = bacteria count so far
        for(int i=1;i<=d;i++){
            long long rem=d-i+1;
            long long x=min(2*p, R/rem);       // largest count still leaving the rest feasible
            s[i-1]=x-p; R-=x; p=x;
        }
        printf("%d\n",d);
        for(int i=0;i<d;i++) printf("%lld%c",s[i],i+1<d?' ':'\n');
    }
}

