    int n; scanf("%d",&n);
    vector<vector<long long>> a(n+1, vector<long long>(n+1));
    vector<long long> s1(2*n+2,0), s2(2*n+2,0);      // anti-diagonal i+j, diagonal i-j+n
    for(int i=1;i<=n;i++) for(int j=1;j<=n;j++){
        scanf("%lld",&a[i][j]);
        s1[i+j]+=a[i][j]; s2[i-j+n]+=a[i][j];
    }
    long long best[2]={LLONG_MIN,LLONG_MIN}; int bx[2]={0,0}, by[2]={0,0};
    for(int i=1;i<=n;i++) for(int j=1;j<=n;j++){
        long long v=s1[i+j]+s2[i-j+n]-a[i][j];     // value attacked by a bishop at (i,j)
        int p=(i+j)&1;                             // bishops on different colours never share a cell
        if(v>best[p]){ best[p]=v; bx[p]=i; by[p]=j; }
    }
    printf("%lld\n%d %d %d %d\n",best[0]+best[1],bx[0],by[0],bx[1],by[1]);
}

#include <bits/stdc++.h>
