int main(){
    int n; long long x;
    scanf("%d %lld",&n,&x);
    vector<long long> d(n);
    for(auto&v:d) scanf("%lld",&v);
    int m=2*n;                                   // doubled year handles wrap-around
    vector<long long> PD(m+1,0), PH(m+1,0);      // prefix days and prefix hugs
    for(int i=0;i<m;i++){
        long long v=d[i%n];
        PD[i+1]=PD[i]+v;
        PH[i+1]=PH[i]+v*(v+1)/2;
    }
    long long best=0;
    for(int i=n;i<m;i++){                        // window ends on the last day of month i
        int lo=i-n+1, hi=i;                      // largest j with days(j..i) >= x
        while(lo<hi){
            int mid=(lo+hi+1)/2;
            if(PD[i+1]-PD[mid]>=x) lo=mid; else hi=mid-1;
        }
        int j=lo;
        long long r=x-(PD[i+1]-PD[j+1]);         // last r days of month j are included
        long long dj=d[j%n];
        long long val=(PH[i+1]-PH[j+1]) + r*(2*dj-r+1)/2;
        best=max(best,val);
    }
    printf("%lld\n",best);
}

