int main(){
    int n,m; scanf("%d %d",&n,&m);
    vector<long long> a(n+1);
    int mn=1;
    for(int i=1;i<=n;i++){ scanf("%lld",&a[i]); if(a[i]<a[mn]) mn=i; }
    vector<tuple<long long,int,int>> e;
    for(int i=1;i<=n;i++) if(i!=mn) e.emplace_back(a[mn]+a[i], mn, i);  // any regular edge can be replaced by one through the cheapest vertex
    for(int i=0;i<m;i++){
        int x,y; long long w; scanf("%d %d %lld",&x,&y,&w);
        e.emplace_back(w,x,y);
    }
    sort(e.begin(),e.end());
    for(int i=1;i<=n;i++) par[i]=i;
    long long ans=0;
    for(auto [w,x,y]:e){
        int rx=find(x), ry=find(y);
        if(rx!=ry){ par[rx]=ry; ans+=w; }   // Kruskal: take the cheapest edge joining two components
    }
    printf("%lld\n",ans);
}

