int main(){
    int t; scanf("%d",&t);                       // scanf skips the blank lines
    while(t--){
        int n,m; scanf("%d %d",&n,&m);
        vector<array<int,3>> e(m);
        for(auto& x:e){ scanf("%d %d %d",&x[0],&x[1],&x[2]); }
        int ans=(1<<30)-1;                       // all weights (<= 1e9 < 2^30) allowed
        for(int b=29;b>=0;b--){
            int cand=ans & ~(1<<b);              // try to forbid bit b
            for(int i=1;i<=n;i++) par[i]=i;
            int comps=n;
            for(auto& x:e) if((x[2] & ~cand)==0){
                int ru=find(x[0]), rv=find(x[1]);
                if(ru!=rv){ par[ru]=rv; comps--; }
            }
            if(comps==1) ans=cand;               // a spanning tree whose OR avoids bit b exists
        }
        printf("%d\n",ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        long long n; int m; scanf("%lld %d",&n,&m);
        vector<long long> cnt(64,0);            // cnt[k] = number of boxes of size 2^k
        long long sum=0;
        for(int i=0;i<m;i++){
            long long a; scanf("%lld",&a); sum+=a;
            cnt[__builtin_ctzll(a)]++;
        }
        if(sum<n){ puts("-1"); continue; }
        long long ans=0;
        for(int k=0;k<62;k++){
            if((n>>k)&1){
                if(cnt[k]==0){                  // borrow the smallest bigger box and split it down to 2^k
                    int j=k+1;
                    while(cnt[j]==0) j++;
                    cnt[j]--;
                    for(int s=k;s<j;s++) cnt[s]++;   // leftover pieces after j-k splits
                    ans+=j-k;
                }
                cnt[k]--;                       // use one box of size 2^k for this bit
            }
            cnt[k+1]+=cnt[k]/2;                 // two unused 2^k boxes merge into one 2^(k+1)
        }
        printf("%lld\n",ans);
    }
}

