int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<long long> a(n+1), A(n+1,0);
        for(int i=1;i<=n;i++){ scanf("%lld",&a[i]); A[i]=A[i-1]+a[i]; }
        long long S=A[n];
        // L: largest lower bound with i*L <= A_i for all i (equivalently L <= floor(A_i / i))
        long long L=S/n;
        for(int i=1;i<n;i++) L=min(L, A[i]/i);
        auto ok=[&](long long d){
            long long R=L+d;                       // final values lie in [L, R]
            if((long long)n*R < S) return false;   // whole array must be able to reach sum S
            for(int j=1;j<n;j++) if(A[j]+(long long)(n-j)*R < S) return false;
            return true;
        };
        long long lo=0, hi=2000000000000LL;        // answer is at most 1e12
        while(lo<hi){
            long long mid=(lo+hi)/2;
            if(ok(mid)) hi=mid; else lo=mid+1;
        }
        printf("%lld\n",lo);
    }
}

#include <bits/stdc++.h>
using namespace std;
vector<int> bfs(int src,const vector<vector<int>>& g){
    vector<int> d(g.size(),-1); queue<int> q; d[src]=0; q.push(src);
    while(!q.empty()){ int u=q.front(); q.pop(); for(int v:g[u]) if(d[v]<0){ d[v]=d[u]+1; q.push(v);} }
    return d;
}
int main(){
    int n,m,k; scanf("%d %d %d",&n,&m,&k);
    vector<int> sp(k); for(auto& x:sp) scanf("%d",&x);
    vector<vector<int>> g(n+1);
    for(int i=0;i<m;i++){ int x,y; scanf("%d %d",&x,&y); g[x].push_back(y); g[y].push_back(x); }
    vector<int> d1=bfs(1,g), dn=bfs(n,g);
    int D=d1[n];
    sort(sp.begin(),sp.end(),[&](int a,int b){ return d1[a]<d1[b]; });  // ascending distance from 1
    vector<int> suf(k+1,-1);                                              // suf[i] = max dn over j >= i
    for(int i=k-1;i>=0;i--) suf[i]=max(suf[i+1], dn[sp[i]]);
    int ans=0;
    for(int i=0;i<k-1;i++){
        // new road sp[i] -> sp[j] with j > i (farther from 1), best j has the largest dn
        ans=max(ans, min(D, d1[sp[i]]+1+suf[i+1]));
    }
    printf("%d\n",ans);
}

