using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll k; scanf("%d %lld",&n,&k);
        vector<ll> a(n), asc, desc, v1; vector<int> b(n);
        for(auto& x:a) scanf("%lld",&x);
        for(auto& x:b) scanf("%d",&x);
        int h=(n+1)/2;                                  // others' median >= T iff >= h of them are >= T
        asc=a; desc=a; sort(asc.begin(),asc.end()); sort(desc.rbegin(),desc.rend());
        for(int i=0;i<n;i++) if(b[i]) v1.push_back(a[i]);
        sort(v1.begin(),v1.end());
        vector<ll> P1(v1.size()+1,0);
        for(size_t i=0;i<v1.size();i++) P1[i+1]=P1[i]+v1[i];
        ll ans=0;
        for(int i=0;i<n;i++){
            if(b[i]){ ll ve=(a[i]>=desc[h-1])?desc[h]:desc[h-1]; ans=max(ans,a[i]+k+ve); }
            else{
                auto ok=[&](ll T){
                    ll ge=(ll)n-(lower_bound(asc.begin(),asc.end(),T)-asc.begin())-(a[i]>=T);
                    if(ge>=h) return true;
                    ll r=h-ge;
                    size_t c=lower_bound(v1.begin(),v1.end(),T)-v1.begin();
                    if((ll)c<r) return false;
                    return r*T-(P1[c]-P1[c-r])<=k;
                };
                ll lo=0, hi=desc[0]+k;
                while(lo<hi){ ll mid=lo+(hi-lo+1)/2; if(ok(mid)) lo=mid; else hi=mid-1; }
                ans=max(ans,a[i]+lo);
            }
        }
        printf("%lld\n",ans);
    }
}

