using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll m; scanf("%d %lld",&n,&m);
        vector<ll> ap(n-1), b(n);
        for(auto& x:ap) scanf("%lld",&x);
        for(auto& x:b) scanf("%lld",&x);
        sort(ap.begin(),ap.end()); sort(b.begin(),b.end());
        // breakpoints of g(v) = #{a'>=v} - #{b>v} are at a'+1 and b
        vector<ll> X;
        for(ll x:ap) X.push_back(x+1);
        for(ll x:b) X.push_back(x);
        sort(X.begin(),X.end()); X.erase(unique(X.begin(),X.end()),X.end());
        const ll NEG=-(ll)4e18;
        vector<ll> st{NEG}; for(ll x:X) st.push_back(x);
        int K=st.size();
        vector<ll> g(K), pre(K), suf(K+1,NEG), bk{1,m+1};
        for(int j=0;j<K;j++){ ll v=j?st[j]:X[0]-1;
            g[j]=(ap.end()-lower_bound(ap.begin(),ap.end(),v))-(b.end()-upper_bound(b.begin(),b.end(),v)); }
        for(int j=0;j<K;j++) pre[j]=j?max(pre[j-1],g[j]):g[j];
        for(int j=K-1;j>=0;j--) suf[j]=max(suf[j+1],g[j]);
        for(int j=1;j<K;j++) if(st[j]>=1 && st[j]<=m+1) bk.push_back(st[j]);
        sort(bk.begin(),bk.end()); bk.erase(unique(bk.begin(),bk.end()),bk.end());
        ll total=0;
        for(size_t k=0;k+1<bk.size();k++){
            ll i=bk[k], len=bk[k+1]-i;
            int j=upper_bound(st.begin(),st.end(),i)-st.begin()-1;
            int q=(int)(lower_bound(st.begin(),st.end(),i+2)-st.begin())-1;
            total+=max<ll>(0,max(pre[j]+1,suf[q]))*len;
        }
        printf("%lld\n",total);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; scanf("%d",&n);
        vector<ll> a(n), b(n), g(n);
        for(auto& x:a) scanf("%lld",&x);
        for(auto& x:b) scanf("%lld",&x);
        ll base=0;
        for(int i=0;i<n;i++){ g[i]=llabs(a[i]-b[i]); base+=g[i]; }
        ll best=0;                                   // doing nothing is allowed
        for(int s1=-1;s1<=1;s1+=2) for(int s2=-1;s2<=1;s2+=2){
            // |a_i-b_j|+|a_j-b_i| = max over signs of f; the swap gain is U_i + V_j for i != j
            vector<ll> U(n), V(n);
            for(int i=0;i<n;i++){
                U[i]= s1*a[i] - s2*b[i] - g[i];
                V[i]= s2*a[i] - s1*b[i] - g[i];
            }
            int u1=-1,u2=-1,v1=-1,v2=-1;
            for(int i=0;i<n;i++){
                if(u1<0 || U[i]>U[u1]){ u2=u1; u1=i; }
                else if(u2<0 || U[i]>U[u2]) u2=i;
                if(v1<0 || V[i]>V[v1]){ v2=v1; v1=i; }
                else if(v2<0 || V[i]>V[v2]) v2=i;
            }
            ll cand;
            if(u1!=v1) cand=U[u1]+V[v1];
            else{
                cand=LLONG_MIN;
                if(v2>=0) cand=max(cand, U[u1]+V[v2]);
                if(u2>=0) cand=max(cand, U[u2]+V[v1]);
            }
            best=max(best,cand);
        }
        printf("%lld\n",base+best);
    }
}

