#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
// smallest x >= n whose digits all lie in D (no leading zero); -1 if none
ll solve(ll n,const vector<int>& D){
    string s=to_string(n); int L=s.size(); bool in[10]={};
    for(int d:D) in[d]=true;
    int mn=*min_element(D.begin(),D.end());
    int pre=0; while(pre<L && in[s[pre]-'0']) pre++;
    if(pre==L) return n;
    for(int p=min(pre,L-1);p>=0;p--){              // keep prefix, bump digit p up
        int c=-1;
        for(int d:D) if(d>s[p]-'0' && (c<0||d<c)) c=d;
        if(c>=0) return stoll(s.substr(0,p)+char('0'+c)+string(L-p-1,char('0'+mn)));
    }
    int first=-1;                                  // otherwise length L+1
    for(int d:D) if(d>0 && (first<0||d<first)) first=d;
    if(first<0) return -1;
    return stoll(string(1,char('0'+first))+string(L,char('0'+mn)));
}
int main(){
    int t; scanf("%d",&t);
    while(t--){
        ll n; int k; scanf("%lld %d",&n,&k);
        ll best=LLONG_MAX;
        for(int a=0;a<=9;a++) for(int b=a;b<=9;b++){
            if(k==1 && a!=b) continue;
            vector<int> D={a}; if(b!=a) D.push_back(b);
            ll r=solve(n,D); if(r>=0) best=min(best,r);
        }
        printf("%lld\n",best);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll s; scanf("%d %lld",&n,&s);
        vector<pair<ll,ll>> e(n);                 // (l, r)
        ll sumL=0;
        for(auto& x:e){ scanf("%lld %lld",&x.first,&x.second); sumL+=x.first; }
        sort(e.begin(),e.end(),[](const pair<ll,ll>& a,const pair<ll,ll>& b){ return a.first>b.first; });
        int k=(n+1)/2;                            // the median and everyone above it must be >= M
        auto ok=[&](ll M){
            int cnt=0; ll extra=0;
            for(auto& x:e){
                if(x.second>=M){                  // eligible: can be paid at least M
                    extra+=max(0LL, M-x.first);  // raise the largest-l eligible ones first (cheapest)
                    if(++cnt==k) break;
                }
            }
            if(cnt<k) return false;
            return sumL+extra<=s;
        };
        ll lo=1, hi=1000000000LL;
        while(lo<hi){
            ll mid=(lo+hi+1)/2;
            if(ok(mid)) lo=mid; else hi=mid-1;
        }
