using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n,s1,s2; scanf("%d %d %d",&n,&s1,&s2); s1--; s2--;
        vector<vector<int>> g1(n), g2(n);
        vector<vector<char>> m1(n, vector<char>(n,0)), m2(n, vector<char>(n,0));
        int m; scanf("%d",&m);
        for(int i=0;i<m;i++){ int a,b; scanf("%d %d",&a,&b); a--; b--; g1[a].push_back(b); g1[b].push_back(a); m1[a][b]=m1[b][a]=1; }
        scanf("%d",&m);
        for(int i=0;i<m;i++){ int a,b; scanf("%d %d",&a,&b); a--; b--; g2[a].push_back(b); g2[b].push_back(a); m2[a][b]=m2[b][a]=1; }
        // a diagonal state (v,v) can keep moving at zero cost iff some u is adjacent to v in both graphs
        vector<int> hdeg(n,0);
        for(int v=0;v<n;v++) for(int u=0;u<n;u++) if(m1[v][u] && m2[v][u]) hdeg[v]++;
        // Dijkstra over pair states (v1,v2) with cost |u1-u2| per simultaneous move
        vector<ll> dist((size_t)n*n, LLONG_MAX);
        priority_queue<pair<ll,int>, vector<pair<ll,int>>, greater<pair<ll,int>>> pq;
        int st=s1*n+s2; dist[st]=0; pq.push({0,st});
        ll ans=-1;
        while(!pq.empty()){
            auto [d,id]=pq.top(); pq.pop();
            if(d!=dist[id]) continue;
            int v1=id/n, v2=id%n;
            if(v1==v2 && hdeg[v1]>0){ ans=d; break; }   // first such state popped is optimal
            for(int u1:g1[v1]) for(int u2:g2[v2]){
                ll nd=d+llabs(u1-u2);
                int nid=u1*n+u2;
                if(nd<dist[nid]){ dist[nid]=nd; pq.push({nd,nid}); }
            }
        }
        printf("%lld\n",ans);
    }
}

#include <bits/stdc++.h>
using namespace std;
// Two of the three strings have at least n copies of the same bit c (pigeonhole).
// Match the first n copies of c in each string; the merge of the unmatched gaps plus n matched bits
// has length (n) + (n) + n = 3n and contains both strings.
int main(){
    int t; scanf("%d",&t);
    static char buf[200005];
    while(t--){
        int n; scanf("%d",&n);
        vector<string> s(3);
        for(int i=0;i<3;i++){ scanf("%s",buf); s[i]=buf; }
        int ci=-1, x=-1, y=-1;
        for(int c=0;c<2 && ci<0;c++){
            char ch='0'+c;
            vector<int> ids;
            for(int i=0;i<3;i++) if(count(s[i].begin(),s[i].end(),ch)>=n) ids.push_back(i);
            if(ids.size()>=2){ ci=c; x=ids[0]; y=ids[1]; }
        }
        const string &A=s[x], &B=s[y];
        char ch='0'+ci;
        vector<int> pa, pb;
        for(int i=0;i<(int)A.size() && (int)pa.size()<n;i++) if(A[i]==ch) pa.push_back(i);
        for(int i=0;i<(int)B.size() && (int)pb.size()<n;i++) if(B[i]==ch) pb.push_back(i);
        string out; out.reserve(3*n);
        int ia=0, ib=0;
        for(int k=0;k<n;k++){
            out.append(A, ia, pa[k]-ia);      // unmatched gap of A
            out.append(B, ib, pb[k]-ib);      // unmatched gap of B
            out.push_back(ch);                // shared matched bit
            ia=pa[k]+1; ib=pb[k]+1;
        }
        out.append(A, ia, string::npos);
        out.append(B, ib, string::npos);
        printf("%s\n",out.c_str());
    }
}

#include <bits/stdc++.h>
using namespace std;
int N;
struct Seg{ vector<int> t; bool mx;   // point set, range max (mx) or min
    void init(int n,bool m){ N=n; mx=m; t.assign(2*n, m?-1:INT_MAX); }
    int f(int x,int y){ return mx? max(x,y) : min(x,y); }
    void set(int p,int v){ for(t[p+=N]=v; p>1; p>>=1) t[p>>1]=f(t[p],t[p^1]); }
    int q(int l,int r){                       // inclusive range
        int res=mx?-1:INT_MAX;
        for(l+=N,r+=N+1;l<r;l>>=1,r>>=1){ if(l&1) res=f(res,t[l++]); if(r&1) res=f(res,t[--r]); }
        return res;
    }
};
int main(){
    int T; scanf("%d",&T);
    while(T--){
        int n; scanf("%d",&n);
        vector<int> a(n), last(n+1,-1), nxt(n,-1), cur(n+1,-1); vector<bool> inR(n+1,false);
        for(auto& x:a) scanf("%d",&x);
        for(int i=0;i<n;i++){ if(last[a[i]]>=0) nxt[last[a[i]]]=i; last[a[i]]=i; }
        multiset<int> ls; Seg mx,mn; mx.init(n,true); mn.init(n,false);
        for(int i=0;i<n;i++) if(!inR[a[i]]){ int v=a[i]; inR[v]=true; cur[v]=i; mx.set(i,v); mn.set(i,v); ls.insert(last[v]); }
        int m=ls.size(), p=0; vector<int> b;
        for(int j=1;j<=m;j++){
            int L=*ls.begin();                // window [p, L]
            int v=(j&1)? mx.q(p,L) : mn.q(p,L), i=cur[v];
            b.push_back(v);
            inR[v]=false; ls.erase(ls.find(last[v])); mx.set(i,-1); mn.set(i,INT_MAX);
            for(int q=p;q<=i;q++) if(cur[a[q]]==q){   // passing an active position
                int w=a[q]; mx.set(q,-1); mn.set(q,INT_MAX);
                if(inR[w] && nxt[q]>=0){ cur[w]=nxt[q]; mx.set(nxt[q],w); mn.set(nxt[q],w); }
            }
            p=i+1;
        }
        printf("%d\n",m);
        for(int x:b) printf("%d ",x);
        puts("");
    }
}

#include <bits/stdc++.h>
using namespace std;
int n,k; vector<int> par, dep;
// can every vertex get depth <= H using at most k cut operations?
int cuts(int H){
    vector<int> best(n+1,-1); int cnt=0;
    for(int v=n;v>=1;v--){                       // children have larger index than parent
        int M=best[v];
        if(dep[v]>H) M=max(M,dep[v]);            // deepest vertex still too deep in subtree of v
        if(M<0) continue;
        if(dep[v]==M-H+1){ cnt++; continue; }    // cut v: it covers everything uncovered below it
        if(v==1) return INT_MAX;                 // should not happen for valid H
        best[par[v]]=max(best[par[v]],M);
    }
    return cnt;
}
int main(){
    int t; scanf("%d",&t);
    while(t--){
        scanf("%d %d",&n,&k);
        par.assign(n+1,0); dep.assign(n+1,0);
        for(int i=2;i<=n;i++){ scanf("%d",&par[i]); dep[i]=dep[par[i]]+1; }
        int maxd=*max_element(dep.begin(),dep.end());
        int lo=1, hi=maxd;                        // height is at least 1, at most the current max depth
        while(lo<hi){ int mid=(lo+hi)/2; if(cuts(mid)<=k) hi=mid; else lo=mid+1; }
        printf("%d\n",lo);
    }
}

#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
int main(){
    int t; scanf("%d",&t);
    while(t--){
        int n; ll k; scanf("%d %lld",&n,&k);
        vector<ll> a(n), b(n);
        for(auto& x:a) scanf("%lld",&x);
        for(auto& x:b) scanf("%lld",&x);
        // index i gives the values a_i, a_i-b_i, ... (positive ones only); count of values >= X:
        auto cnt=[&](ll X){ ll c=0; for(int i=0;i<n;i++) if(a[i]>=X) c+=(a[i]-X)/b[i]+1; return c; };
        auto sumTop=[&](ll X,ll& c){                   // sum and count of values >= X
            ll s=0; c=0;
            for(int i=0;i<n;i++) if(a[i]>=X){
                ll m=(a[i]-X)/b[i]+1;
                s+=m*a[i]-b[i]*m*(m-1)/2; c+=m;
            }
            return s;
        };
        ll ans;
        if(cnt(1)<k){ ll c; ans=sumTop(1,c); }      // not enough positive values: take all of them
        else{
            ll lo=1, hi=*max_element(a.begin(),a.end());
            while(lo<hi){ ll mid=(lo+hi+1)/2; if(cnt(mid)>=k) lo=mid; else hi=mid-1; }
            ll cg; ll sg=sumTop(lo+1,cg);            // all values strictly above X = lo
            ans=sg+(k-cg)*lo;                        // fill the rest with copies of value lo
        }
        printf("%lld\n",ans);
    }
}

