#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; scanf("%d",&n);
    vector<int> p(n);
    for(auto& x:p) scanf("%d",&x);
    // maximal monotone runs: [s,e] with e-s steps
    vector<array<int,2>> runs;
    int s=0;
    for(int i=1;i<n;){
        bool up = p[i]>p[i-1];
        int j=i;
        while(j+1<n && ((p[j+1]>p[j])==up)) j++;
        runs.push_back({i-1,j});
        i=j+1;
    }
    int M=0, cntM=0;
    for(auto& r:runs){ int L=r[1]-r[0]; if(L>M){M=L; cntM=0;} if(L==M) cntM++; }
    int ans=0;
    // Qingshan wins only at a peak x whose two adjacent runs are the only longest runs, with M even
    if(M%2==0 && cntM==2){
        for(size_t k=0;k+1<runs.size();k++){
            if(runs[k][1]-runs[k][0]==M && runs[k+1][1]-runs[k+1][0]==M && runs[k][1]==runs[k+1][0]){
                int x=runs[k][1];
                if(x>0 && x<n-1 && p[x-1]<p[x] && p[x]>p[x+1]) ans=1;
            }
        }
    }
    printf("%d\n",ans);
}
